INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371874, 15865, 'The Guardian', 'en', 'Family of missing 18-year-old hiker ‘absolutely devastated’ as search continues in rugged NSW terrain', 'https://www.theguardian.com/australia-news/2026/aug/18/family-of-missing-18-year-old-hiker-absolutely-devastated-as-search-continues-in-rugged-nsw-terrain', 'Lily Hooper has not been seen since leaving for a hike in Nattai national park, south-west of Sydney, on 12 August Get our breaking news email , free app or daily news podcast The family of missing 18-year-old bushwalker Lily Hooper say they are “absolutely devastated” that she hasn’t been found after a multi-agency search. On Tuesday, search efforts for the teenager continued through the dense tree canopy and rugged terrain of Nattai national park, about 90km south-west of Sydney, for a seventh day. Continue reading...', 'https://i.guim.co.uk/img/media/88767de4bf103f7cd1db7a710fb56defa740aef5/0_51_1638_1309/master/1638.jpg?width=140&quality=85&auto=format&fit=max&s=5030878904c3f726449f80805510b07a', '2026-08-18T08:24:00+00:00', '2026-08-18T09:14:52.151820'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
