INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (366728, 15874, 'Mint', 'en', 'Nasdaq plans 23-hour trading sessions from December 2026 to meet rising global demand for US stocks', 'https://www.livemint.com/market/stock-market-news/nasdaq-plans-23-hour-trading-sessions-from-december-2026-to-meet-rising-global-demand-for-us-stocks-11787024433564.html', 'Nasdaq plans to extend trading hours to 23 hours a day, five days a week, beginning in December 2026. This initiative aims to meet the growing global interest in US stocks while enhancing access to capital for international investors.', 'https://www.livemint.com/lm-img/img/2026/08/18/1600x900/logo/NYSE-TRUMP-50_1741919261406_1787024825571_a24a216e-7cfb-4e58-9b35-cfbf452e7b59.jpg', '2026-08-18T03:48:06+00:00', '2026-08-18T03:59:03.990612'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372210, 15874, 'Euronews', 'en', 'Nasdaq confirms 23-hour trading from December with new overnight session', 'http://www.euronews.com/business/2026/08/18/nasdaq-confirms-23-hour-trading-from-december-with-new-overnight-session', 'Nasdaq will begin trading US stocks for nearly 23 hours a day from 6 December, adding a new overnight session from 9pm to 4am ET, as the exchange races to compete with round-the-clock crypto and tokenised markets and with investors abroad clamouring for access.', '', '2026-08-18T09:05:17+00:00', '2026-08-18T09:19:36.838351'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
