INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372178, 15876, 'South China Morning Post', 'en', 'Myanmar’s president heads to Moscow seeking Russian arms and oil', 'https://www.scmp.com/week-asia/politics/article/3364430/myanmars-president-heads-moscow-seeking-russian-arms-and-oil', 'Russian President Vladimir Putin is set to host Myanmar’s Min Aung Hlaing on Tuesday, as the Southeast Asian leader seeks an economic reboot for his war-ravaged country and fresh supplies of fertiliser, oil and weapons. A pariah to much of the West over his 2021 coup and role as army chief during the ethnic cleansing of the Rohingya Muslim minority, Min Aung Hlaing has nonetheless found friends in Beijing, New Delhi and Bangkok over recent months. That followed a heavily criticised election won...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/0595f1dc-fe08-4ffe-bbcd-8925247ad115_cd713557.jpg?itok=QvGqIMD4&v=1787044535', '2026-08-18T09:15:37+00:00', '2026-08-18T09:19:17.109708'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
