INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369363, 15913, 'The Guardian', 'en', 'Coalition MPs cross floor over ‘weak’ gambling crackdown as major parties strike deal', 'https://www.theguardian.com/australia-news/2026/aug/18/gambling-reforms-betting-ads-labor-coalition-strike-deal', 'Labor’s bill to restrict gambling ads is set to pass this week, with the Greens calling the agreement ‘cowardly’ Two Coalition MPs have crossed the floor after a deal between the major parties to pass Labor’s new restrictions on betting advertising and inducements, which the MPs say are too “weak” and place “too much faith in the hands of the gambling companies”. Anthony Albanese and the communications minister, Anika Wells, secured the support of the opposition to pass the bill, with amendments including tweaks to ad timing rules and some restrictions on inducements . Continue reading...', 'https://i.guim.co.uk/img/media/f20a8fee445c808a928eaccb41efbdedf6c21add/1316_0_6880_5504/master/6880.jpg?width=140&quality=85&auto=format&fit=max&s=e3e2d5e04869d3c0d1c8e8c657579a8a', '2026-08-18T06:09:05+00:00', '2026-08-18T06:41:25.622842'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
